return [{ json: { developer_chat_id: '8677383067', message } }];

const probe = $input.first()?.json ?? {};
const status = Number(probe.statusCode ?? probe.status ?? 0);
const body = (probe.body && typeof probe.body === 'object') ? probe.body : probe;
const apiError = (body && typeof body === 'object' && body.error && typeof body.error === 'object') ? body.error : {};

const code = String(apiError.code || apiError.type || '').toLowerCase();
const providerMessage = String(apiError.message || '').trim();

