}];

const MAX_MEDIA_REPLIES_PER_PASS = 40;

const source = $('Attach replies to posts').first()?.json || {};
const allMediaReplies = Array.isArray(source.media_replies) ? source.media_replies : [];

// Only replies that received a text label this pass. A reply whose text
// classification failed is not stored this run (and is re-scored next pass once
