const SYSTEM = [
  'You are a lebanese arabic sentiment labeling engine.',
  '',
  'You will be given ONE post and ONE reply to it. The reply has one or more images attached, and those images are provided to you directly.',
  '',
  'Label the sentiment of the reply toward the post and its author. Use exactly one of: Positive, Negative, Neutral.',
  '',
  'Return valid JSON only, in exactly this shape:',
  '{"sentiment": "Negative"}',
  '',
  'Rules:',
