  '- An image that flatters or DEFENDS a third party the post criticises IS Negative toward the author, because it dismisses the post and its argument.',
  '- Do not label Negative merely because the image contains angry or insulting language. Identify the target first.',
  '',
  '- Do not include explanations. Output JSON only.'
].join('\n');

if (mediaReplies.length === 0) {
  return [{ json: { no_media: true, media_reply_count: 0 } }];
}

const selected = mediaReplies.slice(0, MAX_MEDIA_REPLIES_PER_PASS);
const skipped = mediaReplies.length - selected.length;

const out = [];
for (const r of selected) {
  const content = [{
    type: 'text',
    text: 'POST by the monitored account:\n' + String(r.postText || '') + '\n\nREPLY to label:\n' + String(r.replyText || '')
  }];
  for (const url of (r.imageUrls || [])) {
    content.push({ type: 'image_url', image_url: { url: url, detail: 'low' } });
  }

  out.push({
    json: {
      no_media: false,
      reply_id: String(r.reply_id),
      post_id: String(r.post_id || ''),
      image_count: (r.imageUrls || []).length,
      skipped_over_cap: skipped,
      body: {
        model: 'gpt-5.4-mini',
        temperature: 0,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: SYSTEM },
          { role: 'user', content: content }
        ]
      }
    }
  });
}

return out;

function parseResults(item) {
  const candidates = [
    item.json?.output?.[0]?.content?.[0]?.text,
    item.json?.output,
    item.json?.text,
  ];

  for (const candidate of candidates) {
    let value = candidate;
    if (typeof value === 'string') {
      try {
        value = JSON.parse(value);
      } catch {
        continue;
      }
    }

    if (Array.isArray(value?.results)) {
      return value.results;
    }
  }

  throw new Error('OpenAI response did not contain a results array.');
}

// Text labels come from Collect Sentiment Labels, which regrouped the per-reply
// Classify Sentiment output into the {results:[...]} shape used here.
const results = $('Collect Sentiment Labels').all().flatMap(item => parseResults(item));

let requests = [];
let responses = [];
try { requests = $('Build Media Classify Requests').all(); } catch (e) { requests = []; }
// Not executed on a pass with no media replies.
try { responses = $('Classify Media Replies').all(); } catch (e) { responses = []; }

const VALID = new Set(['Positive', 'Negative', 'Neutral']);
const overrides = new Map();
let applied = 0;
let failed = 0;

for (let i = 0; i < requests.length; i++) {
  const req = requests[i].json || {};
  if (req.no_media) continue;

  const res = responses[i] ? responses[i].json : null;
  let label = '';
  try {
    const raw = (res && res.choices && res.choices[0] && res.choices[0].message)
      ? res.choices[0].message.content
      : null;
    if (raw) {
      const parsed = (typeof raw === 'string') ? JSON.parse(raw) : raw;
      label = String(parsed.sentiment || '');
    }
  } catch (e) {
    label = '';
  }

  if (VALID.has(label)) {
    overrides.set(String(req.reply_id), label);
    applied += 1;
  } else {
    // Degrade to the text-only label rather than dropping the reply.
    failed += 1;
  }
}

let changed = 0;
for (const post of results) {
  for (const reply of (post.replies || [])) {
    const override = overrides.get(String(reply.id));
    if (!override) continue;
    if (String(reply.sentiment || '') !== override) changed += 1;
    reply.sentiment = override;
    reply.media_labeled = true;
  }
}

return [{
  json: {
    text: JSON.stringify({ results }),
    media_labels_applied: applied,
    media_labels_failed: failed,
    media_labels_changed_from_text: changed,
  },
}];

const data = $json || {};
const which = [
  data.replies_truncated ? 'replies' : null,
  data.posts_truncated ? 'posts' : null,
].filter(Boolean).join(' and ');

return [{
  json: {
    scheduler_alert_type: 'SEARCH_PAGE_CAP_REACHED',
    message: `X ${which} search stopped on the page cap with a next_token still pending, so this pass did not read everything available. `
      + `Reply pages fetched: ${data.reply_page_count ?? 0}; post pages fetched: ${data.post_page_count ?? 0}; `
      + `replies returned: ${data.fetched_reply_count ?? 0}. `
      + 'Because the replies query is incremental, the unread replies are NOT re-requested on the next pass - the run state has already moved past them. '
      + 'Raise maxRequests on the affected node and re-run a backfill with a null Run State watermark.',
    post_count: Array.isArray(data.candidate_post_ids) ? data.candidate_post_ids.length : 0,
    post_ids: Array.isArray(data.candidate_post_ids) ? data.candidate_post_ids : [],
  },
}];

// Reached when a pass ends early with nothing to analyze. Three ways in:
//   - no active tracked users            (If Scheduler Should Continue, false branch)
//   - the posts search returned nothing  (filter sees no items)
//   - no post cleared the 10-reply filter
// All three are successful passes that found no work, so the watermark should
// advance - otherwise a quiet stretch strands it and the next active run pays for
// the whole 7-day fallback window.
//
// The exception is a truncated posts search: a qualifying post may sit on a page we
// never read, so advancing past it would skip those replies permanently. Cost is
// recoverable, missed replies are not, so truncation wins.

function lastPageStillHasToken(pages) {
  const byChunk = new Map();
  pages.forEach((page) => {
    let key = 'unknown';
    const paired = page.pairedItem;
    if (typeof paired === 'number') key = String(paired);
    else if (paired && typeof paired === 'object' && paired.item !== undefined) key = String(paired.item);
    if (!byChunk.has(key)) byChunk.set(key, []);
    byChunk.get(key).push(page);
  });
  for (const group of byChunk.values()) {
    const last = group[group.length - 1];
    if (last?.json?.meta?.next_token) return true;
  }
  return false;
}

let reason = 'NO_QUALIFYING_POSTS';
let postPageCount = 0;
let postsTruncated = false;

try {
  const postPages = $('Get posts of tracked users').all();
  postPageCount = postPages.length;
  postsTruncated = lastPageStillHasToken(postPages);
  const returnedAny = postPages.some(page => (page.json?.data || []).length > 0);
  if (!returnedAny) reason = 'NO_POSTS_RETURNED';
} catch (e) {
  // The posts node never ran, so this is the no-tracked-users pass.
  reason = 'NO_TRACKED_USERS';
}

return [{
  json: {
    quiet_reason: reason,
    post_page_count: postPageCount,
    posts_truncated: postsTruncated,
    fetch_truncated: postsTruncated,
    has_new_replies: false,
    new_reply_count: 0,
  },
}];

// Every post the X search returned this pass, before any suppression or
// reply-count filter. Posts that are Ignored or Snoozed are dropped from the
// analysis path downstream, which used to freeze their counts forever; this
// branch keeps their reply total and engagement current at no extra API cost.
// One row per post: search can return the same post twice (execution 41028),
// and UPDATE ... FROM with duplicate source rows is ambiguous.
const byId = new Map();
for (const item of $input.all()) {
  const id = String(item.json.id || '');
  if (!id) continue;
  const m = item.json.public_metrics || {};
  const n = (v) => (Number.isFinite(Number(v)) ? Number(v) : null);
  byId.set(id, {
    post_id: id,
    reply_count: n(m.reply_count),
    like_count: n(m.like_count),
    retweet_count: n(m.retweet_count),
    quote_count: n(m.quote_count),
    bookmark_count: n(m.bookmark_count),
    impression_count: n(m.impression_count),
