}
const rows = [...byId.values()];
return [{ json: { metrics: JSON.stringify(rows), post_count: rows.length } }];

// One item per NEW reply, each carrying exactly what Classify Sentiment reads.
// Replaces the batched-JSON call (one OpenAI request per client carrying every
// post and reply) with the per-reply shape IG - Monitor uses, so all three
// monitors classify the same way and can later share one prompt.
//
// Replies are read from Attach replies to posts, which already dropped anything
// scored in an earlier pass and any duplicate across chunks, pages or the overlap
// window. A reply that is not in this plan is never sent to OpenAI.

const payloadRaw = $('Attach replies to posts').first()?.json?.text || '{"results":[]}';
let posts = [];
try {
  const parsed = JSON.parse(payloadRaw);
  posts = Array.isArray(parsed.results) ? parsed.results : [];
} catch {
  posts = [];
}

// X author id -> tracked user, from the rows this run already fetched. Carries
// the client (for the per-client cheat sheet) and the display name (so the
// classifier can recognise a reply that addresses the owner by name).
const trackedByAuthorId = new Map(
  $('Get Tracked Users').all().map(item => [
    String(item.json.user_id || ''),
    {
      clientId: String(item.json.client_id || ''),
      username: String(item.json.username || ''),
      displayName: String(item.json.display_name || ''),
    },
  ])
);

// Get Active Cheat Sheets uses alwaysOutputData, so an empty table still yields
// one blank item. Drop anything without both a client and rule text.
const sheetByClientId = new Map(
  $('Get Active Cheat Sheets').all()
    .map(item => item.json || {})
    .filter(row => row.client_id && row.rules_text)
    .map(row => [
      String(row.client_id),
      { version: Number(row.version || 0), rulesText: String(row.rules_text) },
    ])
);

// The classifier's system prompt is a LangChain template: a literal brace in the
// cheat sheet would be read as a placeholder and break the call. Double them.
function escapeTemplateBraces(value) {
  return String(value).split('{').join('{{').split('}').join('}}');
}

// The text the classifier receives for one comment, built from the comment_text
// row's user_template in public."Sentiment Prompts" (placeholders {{owner}},
// {{post}}, {{author_note}}, {{comment}}). The same shape in X, FB and IG: owner,
// then the post (cut at 1000 characters), then the comment.
const USER_TEMPLATE = $('Resolve Sentiment Prompts').first().json.comment_text.user_template;
function fillTemplate(tpl, values) {
  return String(tpl).replace(/\{\{(\w+)\}\}/g, (m, k) => Object.prototype.hasOwnProperty.call(values, k) ? String(values[k]) : m);
}
function composeClassifierInput(p) {
  const owner = '@' + (p.author_username || 'unknown') + (p.author_name ? ' (' + p.author_name + ')' : '');
  let post = p.post_text ? String(p.post_text).trim() : '';
  if (post.length > 1000) post = post.slice(0, 1000) + ' [...]';
  return fillTemplate(USER_TEMPLATE, {
    owner,
    post: post || '(no text)',
    author_note: p.is_owner_reply ? ' (written by the account owner)' : '',
    comment: String(p.reply_text || ''),
  });
}

const out = [];
for (const post of posts) {
  const postId = String(post.postId || '');
  const userId = String(post.userId || '');
  const tracked = trackedByAuthorId.get(userId) || null;
  const clientId = tracked && tracked.clientId ? tracked.clientId : 'unknown';
  const sheet = sheetByClientId.get(clientId) || null;
  const block = sheet
    ? 'Client-specific labelling rules (cheat sheet v' + sheet.version + '). Apply these over your general judgement whenever they match:\n' + sheet.rulesText
    : 'No client-specific labelling rules are configured for this client. Use your general judgement.';

  const authorUsername = String(post.authorUsername || (tracked ? tracked.username : '') || '');
  const authorName = String(post.authorName || (tracked ? tracked.displayName : '') || '');

  for (const reply of (Array.isArray(post.replies) ? post.replies : [])) {
    if (!reply || !reply.id) continue;
    const replyAuthorId = reply.author_id ? String(reply.author_id) : '';
    const isOwnerReply = replyAuthorId !== '' && replyAuthorId === userId;
    const replyText = String(reply.text || '');
    out.push({
      json: {
        post_id: postId,
        post_text: String(post.postText || ''),
        user_id: userId,
        post_author: String(post.postAuthor || ''),
        author_username: authorUsername,
        author_name: authorName,
        // Kept adjacent on purpose: the cheat-sheet isolation fixture asserts the
        // contiguous pairing "client_id":"<uuid>","cheat_sheet_version":<n>.
        client_id: clientId,
        cheat_sheet_version: sheet ? sheet.version : 0,
        cheat_sheet_block: escapeTemplateBraces(block),
        reply_id: String(reply.id),
        reply_text: replyText,
        reply_author_id: replyAuthorId,
        is_owner_reply: isOwnerReply,
        classifier_input: composeClassifierInput({
          author_username: authorUsername,
          author_name: authorName,
          post_text: post.postText,
          is_owner_reply: isOwnerReply,
          reply_text: replyText,
        }),
      },
    });
  }
}

// Nothing to score. Returning no items stops the analysis branch cleanly.
return out;

// Re-groups the per-reply labels by post into the {results:[...]} shape the rest of
// the pipeline has always consumed, so counts, thresholds, alerts, DB writes and
// the watermark gate are unchanged apart from where the labels come from.
//
// Input is Merge Sentiment Results: the three tagged outputs of Classify Sentiment
// plus its error output. An error item carries only {error} - n8n's error output
// drops the original fields - so failures are found by SET DIFFERENCE against
// Build Analysis Plan: any planned reply without a valid label failed.
//
// A failed reply is NOT stored and NOT counted. It keeps analyzed_at null, so the
// next pass re-fetches and re-scores it - but only if the watermark did not move
// past it. If Safe To Advance Watermark (Analyzed) therefore also reads
// classification_failed_count from this node and holds the marker when it is > 0.

const VALID = new Map([
  ['positive', 'Positive'],
  ['neutral', 'Neutral'],
  ['negative', 'Negative'],
]);

const plan = $('Build Analysis Plan').all().map(item => item.json || {});

const labelByReplyId = new Map();
let errorItems = 0;
for (const item of $input.all()) {
  const j = item.json || {};
  const replyId = j.reply_id ? String(j.reply_id) : '';
  const label = VALID.get(String(j.sentiment || '').trim().toLowerCase()) || '';
  if (j.classification_failed === true || !replyId || !label) {
    errorItems += 1;
    continue;
  }
  labelByReplyId.set(replyId, label);
}

const byPost = new Map();
const failedReplyIds = [];
for (const p of plan) {
  const replyId = String(p.reply_id || '');
  const label = labelByReplyId.get(replyId);
  if (!label) {
    failedReplyIds.push(replyId);
    continue;
  }
  const postId = String(p.post_id || '');
  if (!byPost.has(postId)) {
    byPost.set(postId, {
      postId,
      postText: p.post_text || '',
      userId: p.user_id || '',
      postAuthor: p.post_author || '',
      authorUsername: p.author_username || '',
      authorName: p.author_name || '',
      replies: [],
    });
  }
  byPost.get(postId).replies.push({
    id: replyId,
    sentiment: label,
    text: p.reply_text || '',
    author_id: p.reply_author_id || '',
    is_owner_reply: p.is_owner_reply === true,
  });
}

const results = [...byPost.values()];
const classified = results.reduce((sum, post) => sum + post.replies.length, 0);

return [{
  json: {
    text: JSON.stringify({ results }),
    planned_reply_count: plan.length,
    classified_reply_count: classified,
    classification_failed_count: failedReplyIds.length,
    classification_error_items: errorItems,
    failed_reply_ids: failedReplyIds,
    analysis_complete: failedReplyIds.length === 0,
  },
}];

// Reads the shared classifier prompts (public."Sentiment Prompts", one row set per
// Supabase project) and composes what this run sends to OpenAI. ONE item out, read
// by name: $('Resolve Sentiment Prompts').first().json. Same code in X, FB and IG
// apart from the constants below; the table, its placeholders and how the rows
// compose are documented in X-Monitor db/migrations/2026-10-18-sentiment-prompts.sql.
//
// Rows: comment_text and comment_image each say {{target_stance_rules}} where the
// shared rules go, so the rules exist once. comment_text also says
// {{cheat_sheet_block}}; this workflow keeps a marker there and fills it per item with the client cheat sheet.
//
// FALLBACK: a missing or empty row means this run uses the hard-coded copy below
// (the Classify Sentiment prompt as of 2026-10-10, cheat sheet marker included) and Build Sentiment Prompt Warning tells the developer
// chat. A failed READ never reaches this node: Get Sentiment Prompts stops the run.
const CHEAT_SHEET_MARKER = "[[CHEAT_SHEET_BLOCK]]";
const NEEDS_IMAGE_PROMPT = false;
const DEFAULT_MODEL = 'gpt-5.4-mini';
const FALLBACK_COMMENT_TEXT = "You classify replies left on the posts of a Lebanese X (Twitter) account. The account owner uses this to find replies that are AGAINST THEM. Each input gives you the account owner, the text of the post, and one reply. Classify ONLY the reply. The post text is context for working out what the reply refers to and whether it agrees with the owner; never classify the post itself.\n\nReplies may be written in Modern Standard Arabic, Lebanese or other dialectal Arabic in Arabic script, Lebanese Arabic transliterated into Latin letters and numerals (Arabizi/franco-arabe, e.g. \"3ajebne\", \"7elou\", \"mish mnih\"), English, French, or a mix of these within the same reply. Detect the language and dialect automatically and judge from meaning, tone and intent, not from the script used.\n\nDecide by TARGET and STANCE, not by tone. First ask who the reply is aimed at, then whether it is for or against the owner.\n\nNegative: the reply is hostile, critical, insulting, mocking, sarcastic or dismissive toward the account owner, toward this post, or toward the position the post takes. This includes disagreeing with the post's message, attacking the owner's competence, sincerity or motives, telling them to stop posting or go away, and disgust or contempt aimed at the post itself.\n\nPositive: the reply supports, praises, thanks or agrees with the owner or the post. Anger, insults or blame aimed at someone else - the state, the government, politicians, parties, officials, institutions, or society in general - are Positive when they agree with or echo the owner's point. Blaming \"us\" or the public in a way that echoes the post is agreement too. Strong or crude language aimed at a third party does not make a reply Negative.\n\nNeutral: questions, tagging other people, greetings, remarks unrelated to the owner or the post, and replies whose target or stance cannot be determined with reasonable confidence, including bare reactions such as \"Bruh\", \"?\", or emoji that do not clearly praise or attack.\n\nRules:\n- If the post criticises a third party and the reply piles on that same third party or a similar one, that is agreement: Positive.\n- If a reply mixes agreement with a jab at the owner, it is Negative.\n- Choose Negative only when the reply is aimed at the owner, this post, or its position. If you cannot tell who it is aimed at, choose Neutral rather than Negative.\n- A reply written by the account owner is classified by the same rules.\n\n[[CHEAT_SHEET_BLOCK]]\n\nCategorize the reply into one of the following: {categories}. Use the provided formatting instructions. Only output the JSON.";
const FALLBACK_USER_TEMPLATE = "Account owner: {{owner}}\nPost:\n<caption>\n{{post}}\n</caption>\nComment{{author_note}}:\n<comment>\n{{comment}}\n</comment>";
const FALLBACK_COMMENT_IMAGE = null;

const rows = new Map();
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.key && typeof r.system_prompt === 'string' && r.system_prompt.trim() !== '') rows.set(String(r.key), r);
}
const required = ['target_stance_rules', 'comment_text'].concat(NEEDS_IMAGE_PROMPT ? ['comment_image'] : []);
const missing_keys = required.filter(k => !rows.has(k));
const warnings = [];
const rules = rows.get('target_stance_rules') || null;

// The Sentiment Analysis node's system prompt is a LangChain template: {categories}
// is its placeholder, so every OTHER brace must be doubled or the call breaks.
function escapeForLangChain(s) {
  const T = '\u0000CATEGORIES\u0000';
  return s.split('{categories}').join(T).split('{').join('{{').split('}').join('}}').split(T).join('{categories}');
}
function withRules(s) { return s.split('{{target_stance_rules}}').join(rules.system_prompt.trim()); }
function tidy(s) { return s.replace(/\n{3,}/g, '\n\n').trim(); }
function settings(row, label) {
  const model = row && row.model && String(row.model).trim() ? String(row.model).trim() : DEFAULT_MODEL;
  let temperature = row && row.temperature !== null && row.temperature !== undefined ? Number(row.temperature) : 0;
  if (!Number.isFinite(temperature) || temperature < 0 || temperature > 2) { warnings.push(label + '.temperature is not a number in 0-2; used 0'); temperature = 0; }
  return { model, temperature };
}

let comment_text;
const textRow = rows.get('comment_text');
if (textRow && rules) {
  let s = withRules(textRow.system_prompt);
  if (!s.includes('{{cheat_sheet_block}}') && CHEAT_SHEET_MARKER) { warnings.push('comment_text has no {{cheat_sheet_block}}; the cheat sheet was appended at the end'); s += '\n\n{{cheat_sheet_block}}'; }
  s = s.split('{{cheat_sheet_block}}').join('\u0001CHEAT\u0001');
  if (!s.includes('{categories}')) { warnings.push('comment_text has no {categories}; the category list was appended'); s += '\n\nCategorize the comment into one of the following: {categories}.'; }
  s = tidy(escapeForLangChain(s).split('\u0001CHEAT\u0001').join(CHEAT_SHEET_MARKER));
  const tpl = textRow.user_template && String(textRow.user_template).trim() ? String(textRow.user_template) : FALLBACK_USER_TEMPLATE;
  if (tpl === FALLBACK_USER_TEMPLATE && !(textRow.user_template && String(textRow.user_template).trim())) warnings.push('comment_text.user_template is empty; used the hard-coded template');
  comment_text = { source: 'table', system_prompt: s, user_template: tpl, ...settings(textRow, 'comment_text'), updated_at: textRow.updated_at || null };
} else {
  comment_text = { source: 'fallback', system_prompt: FALLBACK_COMMENT_TEXT, user_template: FALLBACK_USER_TEMPLATE, model: DEFAULT_MODEL, temperature: 0, updated_at: null };
}

let comment_image = null;
if (NEEDS_IMAGE_PROMPT) {
  const imageRow = rows.get('comment_image');
  if (imageRow && rules) {
    comment_image = { source: 'table', system_prompt: tidy(withRules(imageRow.system_prompt)), ...settings(imageRow, 'comment_image'), updated_at: imageRow.updated_at || null };
  } else {
    comment_image = { source: 'fallback', system_prompt: FALLBACK_COMMENT_IMAGE, model: DEFAULT_MODEL, temperature: 0, updated_at: null };
  }
}

const fallback_used = comment_text.source === 'fallback' || (comment_image !== null && comment_image.source === 'fallback');
return [{ json: {
  comment_text,
  comment_image,
  fallback_used,
  missing_keys,
  warnings,
  row_count: rows.size
} }];

// One developer line when Resolve Sentiment Prompts fell back to a hard-coded prompt
// or had to repair a row, so a deleted or broken row in public."Sentiment Prompts"
// is never silent. Returns nothing when every row was read cleanly.
const p = $input.first().json;
if (!p.fallback_used && (!p.warnings || p.warnings.length === 0)) return [];
function escapeHtml(v) { return String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
const parts = [];
if (p.missing_keys && p.missing_keys.length) parts.push('Missing or empty rows: ' + p.missing_keys.join(', ') + '. This run used the hard-coded prompt for: ' + [p.comment_text && p.comment_text.source === 'fallback' ? 'comment_text' : null, p.comment_image && p.comment_image.source === 'fallback' ? 'comment_image' : null].filter(Boolean).join(', ') + '.');
for (const w of (p.warnings || [])) parts.push(w);
return [{ json: { scheduler_alert_type: 'SENTIMENT_PROMPT_FALLBACK', message: escapeHtml('public."Sentiment Prompts": ' + parts.join(' ') + ' Labels are still produced; fix the row to stop this warning.') } }];
